import java.util.*;
class Task {String name;Task(String n){name=n;}}
class TaskService {private final List<Task> tasks=new ArrayList<>();void add(String name){if(name==null||name.isBlank())throw new IllegalArgumentException("Task name required");tasks.add(new Task(name));}int count(){return tasks.size();}List<Task> all(){return tasks;}}
public class LayeredApp {static void testAdd(){TaskService s=new TaskService();s.add("Study");if(s.count()!=1)throw new AssertionError("Add test failed");}static void testInvalid(){TaskService s=new TaskService();try{s.add("");throw new AssertionError("Expected exception");}catch(IllegalArgumentException expected){}}static void testMultiple(){TaskService s=new TaskService();s.add("A");s.add("B");if(s.count()!=2)throw new AssertionError("Count test failed");}public static void main(String[] args){testAdd();testInvalid();testMultiple();System.out.println("3 tests passed");Scanner sc=new Scanner(System.in);TaskService service=new TaskService();while(true){System.out.println("1 Add  2 List  3 Exit");int c=sc.nextInt();sc.nextLine();if(c==1){System.out.print("Task: ");service.add(sc.nextLine());}else if(c==2){for(Task t:service.all())System.out.println(t.name);}else break;}}}
